import { readFileSync } from "node:fs";
import { createTransport } from "nodemailer";
import type { SmtpConfig } from "./config.ts";
import { loginCodeEmail } from "./loginEmail.ts";

export interface Mailer {
  sendLoginCode(to: string, code: string): Promise<void>;
}

// Generated by brand/build_brand.py. The path is the same from src/ (dev) and
// dist/ (prod build); the Docker image copies brand/email to match.
const LOGO_URL = new URL("../../../brand/email/logo.png", import.meta.url);
const LOGO_CID = "logo@droid247";

function loadLogo(): Buffer | undefined {
  try {
    return readFileSync(LOGO_URL);
  } catch {
    console.warn(`Email logo not found at ${LOGO_URL.pathname}; emails will use a text logo.`);
    return undefined;
  }
}

export function createSmtpMailer(smtp: SmtpConfig): Mailer {
  const transport = createTransport({
    host: smtp.host,
    port: smtp.port,
    secure: smtp.secure,
    auth: smtp.user ? { user: smtp.user, pass: smtp.pass } : undefined,
  });
  const logo = loadLogo();

  return {
    async sendLoginCode(to, code) {
      const email = loginCodeEmail(code, { logoSrc: logo && `cid:${LOGO_CID}` });
      await transport.sendMail({
        from: smtp.from,
        to,
        ...email,
        attachments: logo
          ? [
              {
                filename: "droid247.png",
                content: logo,
                cid: LOGO_CID,
                contentDisposition: "inline",
              },
            ]
          : [],
      });
    },
  };
}

/** Dev fallback when no SMTP server is configured. */
export const consoleMailer: Mailer = {
  async sendLoginCode(to, code) {
    console.log(`[mail] sign-in code for ${to}: ${code}`);
  },
};
